      shield: 'M12 3l8 3v6c0 4.5-3.4 8.3-8 9-4.6-.7-8-4.5-8-9V6zM9 12l2 2 4-4', lock: 'M7 11V8a5 5 0 0110 0v3M5 11h14v10H5z', hose: 'M6 4v8a6 6 0 0012 0V8M18 4v4',
