        colors: [['br', 'Branco', '#FFFFFF', 0, 'BR'], ['pf', 'Preto fosco', '#2B2B2B', 0, 'PF'], ['cr', 'Cromado', '#C4C8CD', 20, 'CR'], ['cb', 'Cobre escovado', '#B4703F', 30, 'CB']],
        sizeLabel: 'Tamanho do espalhador', sizes: [['15', '15 cm', 0], ['20', '20 cm', 40], ['30', '30 cm', 90]], defSize: '15', out: (c, z) => c === 'cb' && z === '30',
        volts: [['127', '127 V', '5.500 W'], ['220', '220 V', '7.500 W']],
