        shots: [B('6292cf7bfc38ae0a44b5d4f4a204ab0b'), B('78afe4c5504499b012617dc189eada01'), B('0af8cae26a7ddfd9e4e829766fab2e2a')], labels: ['Chuveiro com espalhador', 'Detalhe do espalhador', 'Disponível nas lojas'],
        hl: [[I.temp, 'Controle eletrônico', 'Ajuste fino da temperatura direto no aparelho.'], [I.jato, 'Jato largo e uniforme', 'Espalhador com furos antientupimento.'], [I.tool, 'Instalação simples', 'Encaixe universal de ½ polegada.'], [I.shield, 'Garantia de 1 ano', 'Assistência técnica em todo o Brasil.']],
        helpT: 'Dúvida sobre a voltagem ou o disjuntor?', helpD: 'Nossa equipe técnica confere a instalação com você antes da compra.',
        d1: 'Chuveiro eletrônico com controle de temperatura no próprio aparelho e espalhador de jato largo. Disponível em quatro cores, três tamanhos de espalhador e nas voltagens 127 V e 220 V.',
