        sizeLabel: 'Diâmetro da cúpula', sizes: [['25', '25 cm', 0], ['32', '32 cm', 40], ['40', '40 cm', 90]], defSize: '32', out: (c, z) => c === 'vm' && z === '40',
        volts: null,
        lowStock: (c) => c === 'vm' ? 2 : 25,
